mapper.select:
SELECT o.id, o.order_date AS orderDate, o.order_no AS orderNo, o.sale_type AS saleType, o.generation_method AS generationMethod, o.status AS status, (CASE WHEN COALESCE(o.coupon_amount, 0) > 0 THEN TRUE ELSE FALSE END) AS useCoupon, o.warehouse_name AS warehouseName, o.customer_code AS customerCode, o.customer_name AS customerName, (CASE WHEN o.bookkeeping_time IS NULL THEN 0 ELSE 1 END) AS bookkeepingStatus, FALSE AS forcedTerminated, (CASE WHEN COALESCE(po.cnt, 0) > 0 THEN TRUE ELSE FALSE END) AS hasPurchased, o.total_quantity AS totalQuantity, o.shipped_quantity AS shippedQuantity, o.unshipped_quantity AS unshippedQuantity, o.total_weight AS totalWeight, o.total_volume AS totalVolume, o.bill_amount AS billAmount, dep.dep_account1 AS depositAccount1, dep.dep_amount1 AS depositAmount1, dep.dep_account2 AS depositAccount2, dep.dep_amount2 AS depositAmount2, o.logistics_company AS logisticsCompany, o.waybill_no AS waybillNo, o.shipping_fee AS shippingFee, o.coupon_amount AS couponAmount, o.discount_amount AS discountAmount, o.receiver_name AS receiverName, o.receiver_phone AS receiverPhone, o.shipping_address AS shippingAddress, o.expected_ship_time AS expectedShipTime, o.salesman_name AS salesmanName, o.dept_name AS deptName, o.creator_name AS creatorName, o.submitter_name AS submitterName, o.auditor_name AS auditorName, o.order_remark AS orderRemark, o.buyer_remark AS buyerRemark, o.attachment AS attachment, o.print_count AS printCount, o.submit_time AS submitTime, o.bookkeeping_time AS bookkeepingTime
FROM erp_sale_order o
/* 订金子表：取 sequence 前两条作为订金账户1/2 */ LEFT JOIN ( SELECT t.order_id, MAX(CASE WHEN t.rn = 1 THEN t.account_name END) AS dep_account1, MAX(CASE WHEN t.rn = 1 THEN t.amount END) AS dep_amount1, MAX(CASE WHEN t.rn = 2 THEN t.account_name END) AS dep_account2, MAX(CASE WHEN t.rn = 2 THEN t.amount END) AS dep_amount2 FROM ( SELECT order_id, account_name, amount, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY sequence ASC, id ASC) AS rn FROM erp_sale_order_deposit ) t GROUP BY t.order_id ) dep ON dep.order_id = o.id
/* 是否已采购：反查采购单 source_bill_no（status 小于 4 视为在途，已取消不计） */ LEFT JOIN ( SELECT source_bill_no, COUNT(*) AS cnt FROM erp_purchase_order WHERE deleted = 0 AND status < 4 GROUP BY source_bill_no ) po ON po.source_bill_no = o.order_no
${ew.customSqlSegment}
